activities.codeSnippet:
// Class A: Has ZERO constructors -> Javac generates default
class PlainSensor {
    double reading; // defaults to 0.0
}

// Class B: Has an explicit no-arg constructor written by developer
class CalibratedSensor {
    double reading;

    CalibratedSensor() {
        reading = 22.5; // Custom calibrated baseline
    }
}

public class Main {
    public static void main(String[] args) {
        PlainSensor s1 = new PlainSensor();           // reading is 0.0
        CalibratedSensor s2 = new CalibratedSensor(); // reading is 22.5

        System.out.println("Plain Sensor: " + s1.reading);
        System.out.println("Calibrated Sensor: " + s2.reading);
    }
}

